"use strict";

module.exports = function wasiPolicyProbe() {
  let observed = "unknown";
  try {
    const wasi = require("node:wasi");
    observed = wasi && (typeof wasi.WASI === "function" || typeof wasi.default === "function")
      ? "available"
      : "available-limited";
  } catch (error) {
    const code = String(error && error.code || "");
    observed = code.startsWith("ERR_AUTOJS6") ? "disabled" : "unavailable";
  }
  return {
    observed,
    summary: "wasi:policy-aware/" + ["available", "available-limited", "disabled", "unavailable"].includes(observed),
  };
};
